insert into public.series (slug,title,channel,code_prefix,summary,format,status,sort) values ('ajae','아재개그 배틀','03','VHS-01','자취방 소파 위 퀴즈 배틀. Q1은 춘식의 선공, Q2는 덕구의 역습.','58초 · 주 2회','live',1) on conflict (slug) do update set title=excluded.title, channel=excluded.channel, code_prefix=excluded.code_prefix, summary=excluded.summary, format=excluded.format, status=excluded.status, sort=excluded.sort;
insert into public.series (slug,title,channel,code_prefix,summary,format,status,sort) values ('news','방구석 늬우스','07','VHS-02','합판 뉴스데스크에서 전하는 진짜 황당 뉴스. 1970년대 앵커처럼 과하게 진지하게.','30~58초 · 주 1회','coming',2) on conflict (slug) do update set title=excluded.title, channel=excluded.channel, code_prefix=excluded.code_prefix, summary=excluded.summary, format=excluded.format, status=excluded.status, sort=excluded.sort;
insert into public.series (slug,title,channel,code_prefix,summary,format,status,sort) values ('spinoff','단골 특별전','11','VHS-03','반응 좋은 조연이 주인공. 삼식이 노래방, 옥분 할매 화투 한 판…','30초 · 격주','planned',3) on conflict (slug) do update set title=excluded.title, channel=excluded.channel, code_prefix=excluded.code_prefix, summary=excluded.summary, format=excluded.format, status=excluded.status, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('chunsik','춘식','main',34,'무직 (프로 백수)','자칭 트렌드세터','게으르고 뻔뻔함, 호기심 많고 아는 척함. 축구·담배·라면·허세. 인생은 한 방이라고 믿음.','오늘도 아무것도 안 했는데 뭔가 뿌듯하다.','선공 출제자. 잘난 척하다 자폭하고, 모든 사건을 국가적 위기로 부풀린다.','2002 붉은악마 티셔츠, 청록 추리닝, 담배',null,'/img/faces/chunsik_smug.webp','/img/sheets/chunsik.webp','#E2231A',1) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('deokgu','덕구','main',33,'무직 (사실상 백수)','기상천외 오답러','멍함, 느림, 착함, 눈치 없음. 라면·TV·틀딱 축구·낮잠. 잘 먹고, 잘 틀리고, 잘 놀림당함.','아…몰라… 그냥 대충 살지 뭐…','후공 출제자. 의식의 흐름대로 황당한 오답을 던지다 가끔 뼈 때리는 팩폭.','금 간 안경, 보라색 바람막이, 턱의 밥풀',null,'/img/faces/deokgu_wrong.webp','/img/sheets/deokgu.webp','#7B4BB8',2) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('bonggu','봉구','support',27,'백수 (상시 용돈 구걸형)','밥 냄새 추적자','늘 해맑고 뻔뻔함, 공짜 좋아함, 음식 냄새만 나면 어디든 따라감.','밥 냄새 났지…?! 어디야?! 나도 좀…!!','음식 냄새만 나면 어디든 난입해 판을 깬다.','88번 야구저지, 손선풍기, 편의점 소시지','봉구의 냄새 추적','/img/faces/bonggu.webp','/img/sheets/bonggu.webp','#4A7FC1',3) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('manbok','만복','support',38,'전 역도부 / 자칭 피트니스 코치','자칭 코치','마음 여리고 착한 거구. 엉터리 운동 조언을 진지하게 하고 눈물도 많음.','운동은… 무조건! 많이! 그리고… 일단 버텨요!','엉터리 운동 조언, 허리 통증으로 자폭, 툭하면 감동의 눈물.','한양체육관 민소매, 부서진 배드민턴 라켓, 한약 보양즙','만복 코치의 홈트','/img/faces/manbok.webp','/img/sheets/manbok.webp','#7FA88A',4) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('okbun','옥분','support',63,'주부 (동네 터줏대감)','화투 승부사','평소엔 한없이 순하고 다정한 할머니지만, 화투나 음식이 걸리면 냉혹하고 무자비함.','근데 화투랑 음식 앞에선 아무도 못 말려…!','순한 할매에서 냉혹한 승부사로 돌변하는 반전.','퀼팅 조끼, 고구마 봉지, 효자손','옥분 할매 화투 한 판','/img/faces/okbun.webp','/img/sheets/okbun.webp','#6E9A3A',5) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('samsik','삼식','support',41,'가수 지망생 (전 나이트클럽 가수)','무대 중독자','나이트클럽에서 실패한 가수. 어디서든 무대를 만들고 노래할 기회를 노리는 뻔뻔한 무대 중독자.','오늘도 한 곡 뽑아볼까! 이~예에~!!','어디서든 노래를 시작하고, 가사를 까먹고, 관객에게 굴욕당한다.','노래방 마이크, 가짜 금목걸이, 가죽 점퍼','삼식이 노래방','/img/faces/samsik.webp','/img/sheets/samsik.webp','#8E2C3A',6) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('gwinam','귀남','support',35,'동네 패션 오라클 (자칭 스타일리스트)','패션 오라클','촌스러운 패션을 신념처럼 밀어붙이는, 자기만의 미의식이 확고한 동네 스타일 전도사.','패션은 감각이 아니라 용기야, 용기!','남의 옷차림을 한없이 훈수 두고, 거울 보다 화장 대참사.','코발트 트레이닝복, 지브라 에코백, 왕진주 귀걸이','귀남의 패션 심판','/img/faces/gwinam.webp','/img/sheets/gwinam.webp','#3340A8',7) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('boknam','복남','support',58,'자칭 전문가 (은퇴)','자칭 전문가','뭐든지 ''내가 예전에…''로 시작하는 자칭 전문가. 평생 쌓은 ''경험''이 최고의 스펙이라 믿음.','내가 예전에 말이야… 그때는 말이지…!','과거 미화 훈수, 무시당하면 자존심 상해 라디오 들으며 졸기.','낚시조끼, 빨간 휴대용 라디오, 말린 오징어','방구석 늬우스 원로 해설위원','/img/faces/boknam.webp','/img/sheets/boknam.webp','#A8432E',8) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('malsun','말순','support',52,'아파트 순찰대장 (자칭)','아파트 순찰대장','참견, 감시, 소문 수집, 정의감 과잉, 오지랖.','아파트는 내가 지킨다! 한 집도 그냥 못 지나가!','참견·감시·신고, 무시당하면 대성통곡.','썬캡, 부채, 원예장갑, 마트 카트','늬우스 현장 제보','/img/faces/malsun.webp','/img/sheets/malsun.webp','#E07A2E',9) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('sunja','순자','support',46,'시장 장사 (채소·반찬)','흥정의 여왕','직설, 깐깐, 흥정의 여왕, 십 원도 깎음.','시장 바닥의 순자 누님! 한 푼도 그냥 안 판다!','흥정 배틀, 손님 앞에서만 공손한 이중 표정.','꽃무늬 블라우스, 고무장갑, 대야','순자네 흥정 배틀','/img/faces/sunja.webp','/img/sheets/sunja.webp','#C2306E',10) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('seongchil','성칠','support',31,'무직 (동네 소문 수집가)','동네 소문통','소심, 겁 많음, 수다(귓속말), 호기심 과다. 작은 일도 크게 말함.','동네에 일어나는 건… 다~ 알고 있다…! (…아마도…!)','귓속말로 소문을 퍼뜨리다 ''절대 아님!'' 발뺌.','니트 조끼, 파리채, 휴대폰 파우치','늬우스 소문 특파원','/img/faces/seongchil.webp','/img/sheets/seongchil.webp','#C9A227',11) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
insert into public.characters (slug,name,role,age,job,tagline,personality,quote,comic,props,spinoff,face_url,sheet_url,color,sort) values ('deokchil','덕칠','support',29,'배달 (동네 배달대행)','배달 알뜰왕','아는 척 심한 잔재주꾼, 흥정에 목숨 검. 말은 크게 하는데 금방 들통남.','내가 이거 더 싸게 구할 수 있는데…!','아는 척·흥정에 목숨, 금방 들통나 찌질 눈물.','신속배달 폴로티, 보온병, 전자시계','덕칠의 득템','/img/faces/deokchil.webp','/img/sheets/deokchil.webp','#9DB52A',12) on conflict (slug) do update set name=excluded.name, role=excluded.role, age=excluded.age, job=excluded.job, tagline=excluded.tagline, personality=excluded.personality, quote=excluded.quote, comic=excluded.comic, props=excluded.props, spinoff=excluded.spinoff, face_url=excluded.face_url, sheet_url=excluded.sheet_url, color=excluded.color, sort=excluded.sort;
