insert into public.episodes (series_slug,number,tape_code,title,youtube_id,tiktok_url,reels_url,thumbnail_url,q1,q2,summary,duration_sec,published_at,status) values ('ajae',1,'VHS-0101','[방구석] 춘식&덕구 : 아재개그 EP.#01','JETJ1kDEwls',null,null,'/img/cuts/cut_09.webp','세상에서 제일 가난한 왕은?','왕이 궁전에 가기 싫을 때 하는 말은?','춘식의 ''캡숑짱'' 뇌섹남 퀴즈에 덕구가 집주인 아저씨 오답으로 응수. Q2에서 전세 역전.',58,'2026-11-07T03:00:29Z','published') on conflict (tape_code) do update set series_slug=coalesce(public.episodes.series_slug, excluded.series_slug), number=coalesce(public.episodes.number, excluded.number), title=coalesce(public.episodes.title, excluded.title), youtube_id=coalesce(public.episodes.youtube_id, excluded.youtube_id), tiktok_url=coalesce(public.episodes.tiktok_url, excluded.tiktok_url), reels_url=coalesce(public.episodes.reels_url, excluded.reels_url), thumbnail_url=coalesce(public.episodes.thumbnail_url, excluded.thumbnail_url), q1=coalesce(public.episodes.q1, excluded.q1), q2=coalesce(public.episodes.q2, excluded.q2), summary=coalesce(public.episodes.summary, excluded.summary), duration_sec=coalesce(public.episodes.duration_sec, excluded.duration_sec), published_at=coalesce(public.episodes.published_at, excluded.published_at), status=coalesce(public.episodes.status, excluded.status);
