insert into public.episode_bonus (episode_id,q1_answer,q2_answer,q2_explain,fly_count,note) select id, '최저임금 (최저 + 임금)','궁시렁 궁시렁 (궁 + 싫어)','궁전(宮)에 가기 ''싫어'' → 궁시렁. 춘식은 ''노가리 까러 삐삐 쳐라''라고 했다가 영혼이 빠져나갔다.',null,'덕구의 오답: "팬티에 똥 묻은 줄도 모르고 보일러 안 틀어주는 우리 집 주인아저씨?"' from public.episodes where tape_code='VHS-0101' on conflict (episode_id) do nothing;
  insert into public.jokes (question,answer,wrong_answer,asker) values ('세상에서 제일 가난한 왕은?','최저임금','보일러 안 틀어주는 우리 집 주인아저씨?','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('왕이 궁전에 가기 싫을 때 하는 말은?','궁시렁 궁시렁','내일은 노가리 까러 삐삐 쳐라… 이거지? 완전 따봉이지?','deokgu');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('세상에서 가장 뜨거운 과일은?','천도복숭아','라면 국물에 빠진 귤…?','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('왕이 넘어지면?','킹콩','왕창…?','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('바나나가 웃으면?','바나나킥','바나나 우유… 사 먹으러 가자 형','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('소가 노래를 부르면?','소송','음메~ 이~예에~ (삼식이 형 따라함)','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('세상에서 가장 쉬운 숫자는?','190,000 (십구만 → 쉽구만)','0… 아무것도 안 해도 되니까','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('오리가 얼면?','언덕','오리털 파카?','deokgu');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('반성문을 영어로 하면?','글로벌 (글로 벌)','쏘리 페이퍼…?','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('깨가 죽으면?','주근깨','참기름 됨','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('아몬드가 죽으면?','다이아몬드','아몬드 봉봉…?','deokgu');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('미소의 반대말은?','당기소','된장국 안 먹는 소?','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('소금의 유통기한은?','천일 (천일염)','짠 날까지','chunsik');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('토끼가 쓰는 빗은?','래빗','당근 모양 빗','deokgu');
  insert into public.jokes (question,answer,wrong_answer,asker) values ('신발이 화가 나면?','신발끈','발 냄새로 복수함','chunsik');
